66: function calculateDelay(retriesConsumed, options) {
67: 	const attempt = Math.max(1, retriesConsumed + 1);
68: 	const random = options.randomize ? (Math.random() + 1) : 1;
69: 
70: 	let timeout = Math.round(random * options.minTimeout * (options.factor ** (attempt - 1)));
71: 	timeout = Math.min(timeout, options.maxTimeout);
