109: async function onAttemptFailure({error, attemptNumber, retriesConsumed, startTime, options}) {
110: 	const normalizedError = error instanceof Error
111: 		? error
112: 		: new TypeError(`Non-error was thrown: "${error}". You should only throw errors.`);
