122: 	const maxRetryTime = options.maxRetryTime ?? Number.POSITIVE_INFINITY;
123: 	const delayTime = calculateDelay(retriesConsumed, options);
124: 	const remainingTimeBeforeCallbacks = calculateRemainingTime(startTime, maxRetryTime);
