148: 	const consumeRetry = await options.shouldConsumeRetry(consumeRetryContext);
149: 	const effectiveDelay = consumeRetry && retriesLeft > 0 ? delayTime : 0;
150: 	const context = Object.freeze({
151: 		error: normalizedError,
152: 		attemptNumber,
153: 		retriesLeft,
154: 		retriesConsumed,
155: 		retryDelay: effectiveDelay,
156: 	});
157: 
158: 	await options.onFailedAttempt(context);
159: 
160: 	if (calculateRemainingTime(startTime, maxRetryTime) <= 0) {
161: 		throw normalizedError;
162: 	}
163: 
164: 	const remainingTime = calculateRemainingTime(startTime, maxRetryTime);
