174: 	if (!await options.shouldRetry(context)) {
175: 		throw normalizedError;
176: 	}
177: 
178: 	const remainingTimeAfterShouldRetry = calculateRemainingTime(startTime, maxRetryTime);
179: 
180: 	if (remainingTimeAfterShouldRetry <= 0) {
181: 		throw normalizedError;
182: 	}
