200: export default async function pRetry(input, options = {}) {
201: 	options = {...options};
202: 
203: 	validateRetries(options.retries);
204: 
205: 	if (Object.hasOwn(options, 'forever')) {
206: 		throw new Error('The `forever` option is no longer supported. For many use-cases, you can set `retries: Infinity` instead.');
207: 	}
208: 
209: 	options.retries ??= 10;
210: 	options.factor ??= 2;
211: 	options.minTimeout ??= 1000;
212: 	options.maxTimeout ??= Number.POSITIVE_INFINITY;
213: 	options.maxRetryTime ??= Number.POSITIVE_INFINITY;
214: 	options.randomize ??= false;
215: 	options.onFailedAttempt ??= () => {};
216: 	options.shouldRetry ??= () => true;
217: 	options.shouldConsumeRetry ??= () => true;
218: 
219: 	// Validate numeric options and normalize edge cases
220: 	validateFunctionOption('onFailedAttempt', options.onFailedAttempt);
221: 	validateFunctionOption('shouldRetry', options.shouldRetry);
222: 	validateFunctionOption('shouldConsumeRetry', options.shouldConsumeRetry);
223: 	validateNumberOption('factor', options.factor, {min: 0, allowInfinity: false});
224: 	validateNumberOption('minTimeout', options.minTimeout, {min: 0, allowInfinity: false});
225: 	validateNumberOption('maxTimeout', options.maxTimeout, {min: 0, allowInfinity: true});
226: 	validateNumberOption('maxRetryTime', options.maxRetryTime, {min: 0, allowInfinity: true});
227: 
228: 	// Treat non-positive factor as 1 to avoid zero backoff or negative behavior
229: 	if (!(options.factor > 0)) {
230: 		options.factor = 1;
231: 	}
232: 
233: 	options.signal?.throwIfAborted();
234: 
235: 	let attemptNumber = 0;
236: 	let retriesConsumed = 0;
237: 	const startTime = performance.now();
238: 
239: 	while (Number.isFinite(options.retries) ? retriesConsumed <= options.retries : true) {
240: 		attemptNumber++;
241: 
242: 		try {
243: 			options.signal?.throwIfAborted();
244: 
245: 			const result = await input(attemptNumber);
246: 
247: 			options.signal?.throwIfAborted();
248: 
249: 			return result;
250: 		} catch (error) {
251: 			if (await onAttemptFailure({
252: 				error,
253: 				attemptNumber,
254: 				retriesConsumed,
255: 				startTime,
256: 				options,
257: 			})) {
258: 				retriesConsumed++;
259: 			}
260: 		}
261: 	}
262: 
263: 	// Should not reach here, but in case it does, throw an error
264: 	throw new Error('Retry attempts exhausted without throwing an error.');
265: }
